local autocmd_utils = require("utils.autocmd")
local Buffer = require("neogit.lib.buffer")
local ui = require("neogit.buffers.diff.ui")
local git = require("neogit.lib.git")
local neogit_config = require("neogit.config")

local api = vim.api

local M = {}

---@class JJSection
---@field commit_id string|nil
---@field change_id string|nil
---@field files string[]
---@field diff_lines string[]

---@class JJSessionState
---@field desc_buf integer
---@field desc_win integer
---@field diff_buffer Buffer|nil
---@field sections JJSection[]
---@field active_id string|nil

---@type table<integer, JJSessionState>
local sessions = {}

local default_opts = {
  strip_diff = true,
  width = nil,
}

---@type typeof(default_opts)
local config = vim.deepcopy(default_opts)

--- Clean file path from Jujutsu change line (handling renames e.g. "{old => new}")
---@param raw_path string
---@return string
local function clean_file_path(raw_path)
  local new_name = raw_path:match("{.-%s*=>%s*(.-)}")
  if new_name then
    return new_name
  end
  return vim.trim(raw_path)
end

--- Parse sections, changed files, and any embedded diffs from jjdescription buffer lines
---@param lines string[]
---@return JJSection[] sections, string[] cleaned_lines, boolean has_embedded_diff
function M.parse_buffer_lines(lines)
  ---@type JJSection[]
  local sections = {}
  ---@type JJSection|nil
  local current_section = nil
  ---@type string[]
  local cleaned_lines = {}
  local in_diff = false
  local in_changes = false
  local has_embedded_diff = false

  for _, line in ipairs(lines) do
    local commit_id = line:match("^JJ:%s*describe%s+([0-9a-fA-F]+)")
    if commit_id then
      in_diff = false
      in_changes = false
      current_section = {
        commit_id = commit_id,
        change_id = nil,
        files = {},
        diff_lines = {},
      }
      table.insert(sections, current_section)
      table.insert(cleaned_lines, line)
      goto continue
    end

    local change_id = line:match("^JJ:%s*Change ID:%s*(%w+)")
    if change_id then
      if current_section then
        current_section.change_id = change_id
      else
        current_section = {
          commit_id = nil,
          change_id = change_id,
          files = {},
          diff_lines = {},
        }
        table.insert(sections, current_section)
      end
    end

    if line:find("This commit contains the following changes:") then
      in_changes = true
      table.insert(cleaned_lines, line)
      goto continue
    end

    if in_changes then
      local status, file_path = line:match("^JJ:%s+([MADRCU%?])%s+(.+)$")
      if file_path then
        if current_section then
          table.insert(current_section.files, clean_file_path(file_path))
        end
        table.insert(cleaned_lines, line)
        goto continue
      elseif line:match("^JJ:%s*$") then
        table.insert(cleaned_lines, line)
        goto continue
      else
        in_changes = false
      end
    end

    if line:match("^JJ:%s*ignore%-rest%s*$") then
      in_diff = true
      has_embedded_diff = true
      goto continue
    end

    if in_diff then
      if line:match("^JJ:%s*Lines starting with") or line:match("^JJ:%s*describe") then
        in_diff = false
        table.insert(cleaned_lines, line)
      else
        if current_section then
          table.insert(current_section.diff_lines, line)
        end
      end
      goto continue
    end

    table.insert(cleaned_lines, line)
    ::continue::
  end

  if #sections == 0 then
    table.insert(sections, {
      commit_id = nil,
      change_id = nil,
      files = {},
      diff_lines = {},
    })
  end

  return sections, cleaned_lines, has_embedded_diff
end

--- Find the commit section corresponding to cursor position
---@param desc_buf integer
---@param sections JJSection[]
---@return JJSection
function M.get_section_under_cursor(desc_buf, sections)
  if #sections <= 1 then
    return sections[1]
  end

  local cursor = api.nvim_win_get_cursor(0)
  local row = cursor[1]

  for l = row, 1, -1 do
    local line_tbl = api.nvim_buf_get_lines(desc_buf, l - 1, l, false)
    local line = line_tbl[1]
    if line then
      local commit_id = line:match("^JJ:%s*describe%s+([0-9a-fA-F]+)")
      if commit_id then
        for _, sec in ipairs(sections) do
          if sec.commit_id == commit_id then
            return sec
          end
        end
      end
    end
  end

  local line_count = api.nvim_buf_line_count(desc_buf)
  for l = row, line_count do
    local line_tbl = api.nvim_buf_get_lines(desc_buf, l - 1, l, false)
    local line = line_tbl[1]
    if line then
      local change_id = line:match("^JJ:%s*Change ID:%s*(%w+)")
      if change_id then
        for _, sec in ipairs(sections) do
          if sec.change_id == change_id then
            return sec
          end
        end
      end
    end
  end

  return sections[1]
end

--- Get a unique identifier for a section
---@param section JJSection
---@param index integer
---@return string
local function get_section_id(section, index)
  return section.commit_id or section.change_id or tostring(index)
end

--- Fetch raw diff from jj command line
---@param rev string
---@param files? string[]
---@return string[]
local function fetch_raw_jj_diff(rev, files)
  local cmd = { "jj", "diff", "--stat", "--git", "-r", rev }
  if files and #files > 0 then
    for _, f in ipairs(files) do
      table.insert(cmd, f)
    end
  end

  local res = vim.system(cmd, { text = true }):wait()
  if res.code == 0 and res.stdout and res.stdout ~= "" then
    return vim.split(res.stdout, "\r?\n", { trimempty = true })
  end
  return {}
end

--- Parse raw stat and diff lines into Neogit DiffView component args
---@param raw_lines string[]
---@param header_title string
---@return table stats, table diffs
function M.parse_diff_content(raw_lines, header_title)
  local stat_lines = {}
  local file_diff_chunks = {}
  local current_diff_chunk = {}
  local in_stat = true

  for _, line in ipairs(raw_lines) do
    if line:match("^diff %-%-git") then
      in_stat = false
      if #current_diff_chunk > 0 then
        table.insert(file_diff_chunks, current_diff_chunk)
        current_diff_chunk = {}
      end
    end

    if in_stat then
      table.insert(stat_lines, line)
    else
      table.insert(current_diff_chunk, line)
    end
  end

  if #current_diff_chunk > 0 then
    table.insert(file_diff_chunks, current_diff_chunk)
  end

  -- Parse stats
  local files = {}
  local summary = nil
  for _, line in ipairs(stat_lines) do
    if line:match("^%s*%d+ file[s ]+changed") then
      summary = vim.trim(line)
    else
      local p, c, signs = line:match("^%s*(.-)%s*|%s*(%d+)%s*([%+%-]*)$")
      if p and c then
        local _, plus_count = (signs or ""):gsub("%+", "")
        local _, minus_count = (signs or ""):gsub("%-", "")
        table.insert(files, {
          path = vim.trim(p),
          changes = c,
          insertions = string.rep("+", plus_count),
          deletions = string.rep("-", minus_count),
        })
      end
    end
  end

  local stats = {
    summary = summary or (#files > 0 and string.format("%d file%s changed", #files, #files == 1 and "" or "s") or ""),
    files = files,
  }

  -- Parse diff chunks via Neogit's git.diff.parse
  local diffs = {}
  for _, chunk in ipairs(file_diff_chunks) do
    local ok, parsed = pcall(git.diff.parse, chunk, {})
    if ok and parsed then
      table.insert(diffs, parsed)
    end
  end

  return stats, diffs
end

--- Resolve raw diff lines for a given section, falling back across valid revisions
---@param section JJSection
---@param all_sections JJSection[]
---@return string[]
local function resolve_section_raw_diff(section, all_sections)
  local diff = {}
  local rev = section.change_id or section.commit_id
  local files = (#all_sections > 1 and #section.files > 0) and section.files or nil

  if rev then
    diff = fetch_raw_jj_diff(rev, files)
  end

  if #diff == 0 and #section.files > 0 then
    for _, other in ipairs(all_sections) do
      local other_rev = other.change_id or other.commit_id
      if other_rev and other_rev ~= rev then
        diff = fetch_raw_jj_diff(other_rev, section.files)
        if #diff > 0 then
          break
        end
      end
    end
    if #diff == 0 then
      diff = fetch_raw_jj_diff("@", section.files)
    end
  end

  return diff
end

--- Build component for a section
---@param session JJSessionState
---@param section JJSection
---@return any component
local function build_section_component(session, section)
  local raw_diff = section.diff_lines
  if not raw_diff or #raw_diff == 0 then
    raw_diff = resolve_section_raw_diff(section, session.sections)
    section.diff_lines = raw_diff
  end

  local header_title = "Changes"
  if section.commit_id then
    header_title = string.format("Commit %s", section.commit_id)
  elseif section.change_id then
    header_title = string.format("Change %s", section.change_id)
  end

  local stats, diffs = M.parse_diff_content(raw_diff, header_title)
  return ui.DiffView(header_title, stats, diffs)
end

--- Update the diff buffer content with the given section's diff
---@param session JJSessionState
---@param section JJSection
---@param section_id string
local function update_diff_buffer(session, section, section_id)
  if session.active_id == section_id then
    return
  end
  session.active_id = section_id

  if not session.diff_buffer or not session.diff_buffer:is_valid() then
    return
  end

  local comp = build_section_component(session, section)
  session.diff_buffer.ui:render(unpack(comp))

  if session.diff_buffer.win_handle and api.nvim_win_is_valid(session.diff_buffer.win_handle) then
    pcall(api.nvim_win_set_cursor, session.diff_buffer.win_handle, { 1, 0 })
  end
end

--- Create the diff Buffer using Neogit's Buffer.create
---@param session JJSessionState
---@param initial_section JJSection
---@return Buffer
local function create_diff_buffer(session, initial_section)
  local status_maps = neogit_config.get_reversed_status_maps()
  local commit_editor_maps = neogit_config.get_reversed_commit_editor_maps()

  local mappings = {
    n = {
      ["{"] = function(buf)
        local function previous_hunk_header(line)
          local c = buf.ui:get_component_on_line(line, function(comp)
            return comp.options.tag == "Diff" or comp.options.tag == "Hunk"
          end)

          if c then
            local first, _ = c:row_range_abs()
            if vim.fn.line(".") == first then
              first = previous_hunk_header(line - 1)
            end
            return first
          end
        end

        local prev = previous_hunk_header(vim.fn.line("."))
        if prev then
          api.nvim_win_set_cursor(0, { prev, 0 })
          vim.cmd("normal! zt")
        end
      end,
      ["}"] = function(buf)
        local c = buf.ui:get_component_under_cursor(function(comp)
          return comp.options.tag == "Diff" or comp.options.tag == "Hunk"
        end)

        if c then
          if c.options.tag == "Diff" then
            buf:move_cursor(vim.fn.line(".") + 1)
          else
            local _, last = c:row_range_abs()
            if last == vim.fn.line("$") then
              buf:move_cursor(last)
            else
              buf:move_cursor(last + 1)
            end
          end
          vim.cmd("normal! zt")
        end
      end,
    },
  }

  -- Toggle fold mapping from Neogit config
  local toggle_keys = commit_editor_maps["Toggle"] or status_maps["Toggle"] or { "za" }
  for _, key in ipairs(type(toggle_keys) == "table" and toggle_keys or { toggle_keys }) do
    mappings.n[key] = function()
      pcall(vim.cmd, "normal! za")
    end
  end

  -- Close mapping from Neogit config (e.g. gq)
  local close_keys = commit_editor_maps["Close"] or status_maps["Close"] or { "gq" }
  for _, key in ipairs(type(close_keys) == "table" and close_keys or { close_keys }) do
    mappings.n[key] = function()
      M.toggle(session.desc_buf)
    end
  end

  local kind = neogit_config.values.commit_editor and neogit_config.values.commit_editor.staged_diff_split_kind
    or "vsplit"

  local buf = Buffer.create({
    name = "NeogitDiffView",
    filetype = "NeogitDiffView",
    status_column = not neogit_config.values.disable_signs and "" or nil,
    kind = kind,
    context_highlight = not neogit_config.values.disable_context_highlighting and neogit_config.values.log_pager == nil,
    mappings = mappings,
    render = function()
      return build_section_component(session, initial_section)
    end,
    after = function(b)
      vim.cmd("normal! zR")
      vim.wo.colorcolumn = ""
      if config.width and b.win_handle and api.nvim_win_is_valid(b.win_handle) then
        pcall(api.nvim_win_set_width, b.win_handle, config.width)
      end
    end,
  })

  return buf
end

--- Get session for buffer
---@param desc_buf integer
---@return JJSessionState|nil
function M.get_session(desc_buf)
  return sessions[desc_buf]
end

--- Toggle the diff split window (can be called as a Lua function)
---@param desc_buf? integer
function M.toggle(desc_buf)
  desc_buf = desc_buf or api.nvim_get_current_buf()
  local session = sessions[desc_buf]
  if not session then
    return
  end

  if session.diff_buffer and session.diff_buffer:is_visible() then
    session.diff_buffer:close()
  else
    local cur_win = api.nvim_get_current_win()
    local cur_section = M.get_section_under_cursor(desc_buf, session.sections)
    local cur_id = get_section_id(cur_section, 1)

    session.active_id = cur_id
    session.diff_buffer = create_diff_buffer(session, cur_section)

    if api.nvim_win_is_valid(cur_win) then
      api.nvim_set_current_win(cur_win)
    end
  end
end

--- Close diff window and buffer
---@param desc_buf integer
function M.close(desc_buf)
  local session = sessions[desc_buf]
  if not session then
    return
  end
  sessions[desc_buf] = nil

  if session.diff_buffer then
    local buf_obj = session.diff_buffer
    session.diff_buffer = nil

    pcall(function()
      if buf_obj.handle and api.nvim_buf_is_valid(buf_obj.handle) then
        local winnr = vim.fn.bufwinnr(buf_obj.handle)
        if winnr ~= -1 then
          local winid = vim.fn.win_getid(winnr)
          if api.nvim_win_is_valid(winid) then
            api.nvim_win_close(winid, true)
          end
        end
        api.nvim_buf_delete(buf_obj.handle, { force = true })
      end
    end)
  end
end

--- Attach jj diff viewer to a jjdescription buffer
---@param desc_buf integer
function M.attach(desc_buf)
  if sessions[desc_buf] then
    return
  end

  local lines = api.nvim_buf_get_lines(desc_buf, 0, -1, false)
  local sections, cleaned_lines, has_embedded_diff = M.parse_buffer_lines(lines)

  -- Strip diff lines from description buffer if any were embedded
  if config.strip_diff and has_embedded_diff then
    local old_undolevels = vim.bo[desc_buf].undolevels
    vim.bo[desc_buf].undolevels = -1
    api.nvim_buf_set_lines(desc_buf, 0, -1, false, cleaned_lines)
    vim.bo[desc_buf].undolevels = old_undolevels
    vim.bo[desc_buf].modified = false
  end

  local cur_win = api.nvim_get_current_win()
  local initial_section = M.get_section_under_cursor(desc_buf, sections)
  local initial_id = get_section_id(initial_section, 1)

  local session = {
    desc_buf = desc_buf,
    desc_win = cur_win,
    diff_buffer = nil,
    sections = sections,
    active_id = initial_id,
  }
  sessions[desc_buf] = session

  session.diff_buffer = create_diff_buffer(session, initial_section)

  if api.nvim_win_is_valid(cur_win) then
    api.nvim_set_current_win(cur_win)
  end

  -- Setup buffer autocmds for cursor tracking and cleanup
  local group_name = string.format("jj_diff_%d", desc_buf)
  local group = api.nvim_create_augroup(group_name, { clear = true })

  api.nvim_create_autocmd({ "CursorMoved", "CursorMovedI" }, {
    group = group,
    buffer = desc_buf,
    callback = function()
      local s = sessions[desc_buf]
      if not s then
        return
      end
      local current_section = M.get_section_under_cursor(desc_buf, s.sections)
      local current_id = get_section_id(current_section, 1)
      update_diff_buffer(s, current_section, current_id)
    end,
    desc = "JJ Diff: update diff on cursor move between commit descriptions",
  })

  api.nvim_create_autocmd("QuitPre", {
    group = group,
    buffer = desc_buf,
    callback = function()
      M.close(desc_buf)
    end,
    desc = "JJ Diff: close diff window before quitting description buffer",
  })

  api.nvim_create_autocmd({ "BufWipeout", "BufDelete" }, {
    group = group,
    buffer = desc_buf,
    callback = function()
      M.close(desc_buf)
      pcall(api.nvim_del_augroup_by_id, group)
    end,
    desc = "JJ Diff: close diff window and clean up when description buffer is closed",
  })
end

--- Setup the jj diff plugin
---@param opts? table
function M.setup(opts)
  if opts then
    config = vim.tbl_deep_extend("force", config, opts)
  end

  autocmd_utils.create_augroups({
    jj_diff = {
      {
        event = "FileType",
        pattern = "jjdescription",
        callback = function(args)
          M.attach(args.buf)
        end,
        desc = "JJ Diff: open diff buffer alongside jjdescription buffer",
      },
    },
  })
end

return M
